import { RendererCanvas } from '../../workshop-vector/base/RendererCanvas';
import { getImgFromURL } from '../../../../lib'

const getSlider = (title: string, min: number, max: number) => {
    // <input type="range" min="1" max="100" value="50" class="slider" id="myRange">
    const div = document.createElement('div');
    div.style.display = 'flex';

    const slider = document.createElement('input');
    slider.type = 'range';
    slider.min = `${min}`;
    slider.max = `${max}`;

    const text = document.createElement('div');
    text.textContent = title;
    text.style.color = '#aaa';
    div.appendChild(slider);
    div.appendChild(text);
    return {
        div, slider, text
    }
};

export class Solution extends RendererCanvas {
    public t: number = 0.0;
    public pMap: PixelMap = undefined;
    public rx: number = 20;
    public ry: number = 20;
    public size: number = 300;
    public img: HTMLImageElement;
    public divMenu: HTMLElement;
    constructor(id: string) {
        super(document.getElementById(id) as HTMLDivElement);
        this.ctx.translate(this.ctx.canvas.width * 0.5, this.ctx.canvas.height * 0.5);
        this.init();

        const divMenu = document.createElement('div');
        this.divMenu = divMenu;
        this.divHost.appendChild(divMenu);
        divMenu.style.display = 'block';
        divMenu.style.position = 'absolute';
        divMenu.style.top = '0px';

        const path0 = 'https://upload.wikimedia.org/wikipedia/commons/5/57/Heightmap.png';
        const path1 = 'https://upload.wikimedia.org/wikipedia/commons/1/15/Srtm_ramp2.world.21600x10800.jpg';
        const path2 = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/heightMap/Heightmap_01.png';
        const path3 = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/heightMap/Heightmap_02.jpg';
        const path4 = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/heightMap/Heightmap_03.jpg';


        const divInput = document.createElement('input');
        // divInput.value = 'https://upload.wikimedia.org/wikipedia/commons/f/ff/Mozilla_Firefox_logo_2013.png';
        divInput.value = path0
        divInput.addEventListener('keydown', (e: KeyboardEvent) => {
            if (e.code === 'Enter') {
                this.importImage(divInput.value)
            }
        });
        divMenu.appendChild(divInput);

        const slType = getSlider('rx', 10, 30)
        slType.slider.defaultValue = '20';
        divMenu.appendChild(slType.div);
        slType.slider.oninput = () => {
            const value = parseInt(slType.slider.value);
            this.rx = value;
            this.init();
        };
        const slType2 = getSlider('ry', 10, 30)
        slType2.slider.defaultValue = '20';
        divMenu.appendChild(slType2.div);
        slType2.slider.oninput = () => {
            const value = parseInt(slType2.slider.value);
            this.ry = value;
            this.init();
        };

        const slType3 = getSlider('size', 100, 500)
        slType3.slider.defaultValue = '300';
        divMenu.appendChild(slType3.div);
        slType3.slider.oninput = () => {
            const value = parseInt(slType3.slider.value);
            this.size = value;
            this.init();
        };


        this.importImage('https://upload.wikimedia.org/wikipedia/commons/f/ff/Mozilla_Firefox_logo_2013.png')
    }
    public importImage(path: string) {
        getImgFromURL(path).then((img: HTMLImageElement | void) => {
            if (!img) return;
            this.img = img;
            this.img.onload = (ev) => {
                this.update(img);
            };
        });
    }
    public update(img: HTMLImageElement) {
        this.img = img        
        this.init()
    }
    public init() {
        const resX = this.rx;
        const resY = this.ry;
        const size = this.size;

        this.pMap = new PixelMap(new Vector3(-size, -size, 0), new Vector3(size, size, 0) ,resX, resY);

        if (this.img) {
            this.pMap.updateImage(this.img)

        }


        this.start();
    }
    public render(ctx: CanvasRenderingContext2D): void {
        this.pMap.render(ctx);

        // this.img && this.ctx.drawImage(this.img, this.img.width * -0.5, this.img.height * -0.5)
    }
    public mouseMove(x: number, y: number): void {
        this.pMap.picking(x - this.ctx.canvas.width * 0.5, y - this.ctx.canvas.height * 0.5);
    }

    public mouseClick(x: number, y: number): void {
        //
    }
    public destroyPost() {
        try {
            while (this.divHost && this.divHost.lastElementChild) {
                const lastChild = this.divHost.lastElementChild as Node;
                this.divHost.removeChild(lastChild);
            }
        } catch (error) {
            console.error('Error removing child elements:', error);
        }
        
    }
}

export class PixelMap {
    public pixelList: Pixel[] = []
    public minV: Vector3;
    public maxV: Vector3;
    public rx = 10;
    public ry = 10;
    public intervalX;
    public intervalY;
    public selPixel: Pixel | undefined = undefined;
    constructor(minV: Vector3, maxV: Vector3, rx: number, ry: number) {
        this.minV = minV;
        this.maxV = maxV;
        this.rx = rx;
        this.ry = ry;
        this.init()
        this.initGridNeighbor();
    }
    public init(){
        this.pixelList = []
        const x = this.minV.x
        const y = this.minV.y

        this.intervalX = (this.maxV.x - this.minV.x) / (this.rx - 1)
        this.intervalY = (this.maxV.y - this.minV.y) / (this.ry - 1)
        
        for(let j = 0 ; j < this.ry; j++) {
            for(let i = 0 ; i < this.rx; i++) {
                const xV = x + i * this.intervalX;
                const yV = y + j * this.intervalY;

                let pix = new Pixel(this, xV , yV , 0);
                pix.xi = i;
                pix.yi = j;
                this.pixelList.push(pix);
            }
        }

    }
    private initGridNeighbor() {
        for (let j = 0; j < this.ry; ++j) {
            for (let i = 0; i < this.rx; ++i) {
                let k = i + j * this.rx;
                let px = this.pixelList[k];
                if (i > 0) { px.nPix.push(this.pixelList[k - 1]); }
                if (i < this.rx - 1) { px.nPix.push(this.pixelList[k + 1]); }
                if (j > 0) { px.nPix.push(this.pixelList[k - this.rx]); }
                if (j < this.ry - 1) { px.nPix.push(this.pixelList[k + this.rx]); }
                if ((i > 0) && (j < this.ry - 1)) { px.nPix.push(this.pixelList[k + this.rx - 1]); }
                if ((i > 0) && (j > 0)) { px.nPix.push(this.pixelList[k - this.rx - 1]); }
                if ((i < this.rx - 1) && (j < this.ry - 1)) { px.nPix.push(this.pixelList[k + this.rx + 1]); }
                if ((i < this.rx - 1) && (j > 0)) { px.nPix.push(this.pixelList[k - this.rx + 1]); }
            }
        }
    }
    public updateImage(img: HTMLImageElement) {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, img.width, img.height, 0, 0, this.rx, this.ry)

        const imgData = ctx.getImageData(0, 0, this.rx, this.ry);

        const px = (x: number, y: number) => {
            return x * 4 + y * imgData.width * 4;
        };

        for (let j = 0; j < this.ry; ++j) {
            for (let i = 0; i < this.rx; ++i) {
                let k = px(i, j)
                let indexList = i + j * this.rx;

                this.pixelList[indexList].color = [
                    imgData.data[k], imgData.data[k+1], imgData.data[k+2], imgData.data[k+3]
                ]
            }
        }
    }
    public picking(x: number, y: number) {
        const mv = new Vector3(x,y,0)
        let dis = Number.MAX_VALUE;
        let id = -1
        for(let i = 0 ; i < this.pixelList.length; ++i) {
           const theDis = distance(this.pixelList[i].vec, mv);
           if (dis > theDis) {
            dis = theDis;
            id = i;
           }
           this.pixelList[i].hover = false;
        }

        this.selPixel = undefined;
        if (id > -1) {
            this.pixelList[id].hover = true;
            this.selPixel = this.pixelList[id];
        }
    }
    public render(ctx) {
        this.pixelList.forEach((p: Pixel) => {
            p.render(ctx);
        })

        if (this.selPixel) {
            this.selPixel.render(ctx);
        }
    }
}

class Pixel {
    public xi: number;
    public yi: number;
    public pMap: PixelMap;
    public vec: Vector3;
    public hover: boolean = false;
    public nPix: Pixel[] = [];
    public color: number[] = [];
    constructor(pMap: PixelMap, x: number, y: number, z: number) {
        this.pMap = pMap;
        this.vec = new Vector3(x,y,z);
    }
    public render(ctx: CanvasRenderingContext2D) {
        const width = this.pMap.intervalX 
        const height = this.pMap.intervalY

        ctx.beginPath()
        ctx.rect(this.vec.x - width * 0.5, this.vec.y - height * 0.5, width, height)
        ctx.closePath()
        ctx.stroke()
        if (this.hover) {
            ctx.fillStyle = '#555';
            ctx.fill()
        } else {
            ctx.fillStyle = `rgba(${this.color[0]}, ${this.color[1]}, ${this.color[2]}, ${this.color[3]})`;
            ctx.fill()
        }

        ctx.beginPath();
        ctx.arc(this.vec.x, this.vec.y, this.vec.r, 0, Math.PI * 2.0);
        ctx.closePath();
        if (this.hover) {
            ctx.fillStyle = '#999';
        } else {
            ctx.fillStyle = '#333';
        }
        ctx.fill();

        if (this.hover) {
            for(let i = 0 ; i < this.nPix.length; ++i) {
                ctx.beginPath();
                ctx.moveTo(this.vec.x, this.vec.y)
                ctx.lineTo(this.nPix[i].vec.x, this.nPix[i].vec.y)
                ctx.closePath();
                ctx.stroke()
            }

            ctx.strokeText(`x: ${this.xi}, y: ${this.yi}` ,this.vec.x, this.vec.y)
        }

        
    }
}

class Vector3 {
    public x: number = 0.0;
    public y: number = 0.0;
    public z: number = 0.0;
    public r: number = 3
    constructor(x,y,z) {
        this.x = x;
        this.y = y;
        this.z = z;
    }
}


const distance = (v0: Vector3, v1: Vector3) => {
    return Math.sqrt(distance2(v0, v1));
}
const distance2 = (v0: Vector3, v1: Vector3) => {
    return (v0.x - v1.x) * (v0.x - v1.x) + (v0.y - v1.y) * (v0.y - v1.y) + (v0.z - v1.z) * (v0.z - v1.z);
}